package com.example

/**
 * High-quality, 100% curriculum-accurate Question Bank for History (ඉතිහාසය)
 * Covers 10 distinct syllabus lessons with 10 unique MCQs per set (100 total distinct questions).
 */
object QuizBankHistory {

  fun getQuestion(
    grade: String,
    setIdx: Int,
    qIdx: Int,
    qNumber: Int,
    topic: String
  ): QuizQuestion {
    return when (setIdx) {
      // SET 1: ප්‍රාග් ඓතිහාසික යුගය හා ජනාවාස
      1 -> when (qIdx) {
        1 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික මානවයා විද්‍යාත්මකව හඳුන්වන්නේ කුමන නමකින්ද?", listOf("හෝමෝ ඉරෙක්ටස්", "හෝමෝ සේපියන්ස් බලන්ගොඩෙන්සිස් (බලන්ගොඩ මානවයා)", "නියැන්ඩර්තාල් මානවයා", "ජාවා මානවයා"), 1, "බලන්ගොඩ බෙල්ලන්බැඳිපැලැස්සෙන් හමුවූ සාධක මත පදනම්ව ආචාර්ය දැරණියගල මහතා මෙම නම තැබීය.")
        2 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ පැරණිතම මානව ජනාවාස සාධක හමුවූ පහතරට තෙත් කලාපීය ලෙන් සංකීර්ණයක් කුමක්ද?", listOf("පාහියන්ගල ලෙන (බුලත්සිංහල)", "සීගිරිය", "දඹුල්ල", "මිහින්තලේ"), 0, "පාහියන්ගල ලෙනෙන් වසර 37,000 කට වඩා පැරණි මානව ඇටසැකිලි හා ජ්‍යාමිතික ක්ෂුද්‍ර ශිලා මෙවලම් හමුවී ඇත.")
        3 -> QuizQuestion(qNumber, "බලන්ගොඩ මානවයා ආහාර පිසීමට සහ මෙවලම් තැනීමට යොදාගත් ප්‍රධාන ද්‍රව්‍යය කුමක්ද?", listOf("යකඩ සහ තඹ", "ක්වාර්ට්ස් (තිරුවාණා) හා කහඳ පාෂාණ සහ සත්ව අස්ථි", "ලෝකඩ", "ප්ලාස්ටික්"), 1, "ක්ෂුද්‍ර ශිලා යුගයේදී සත්ව ඇටකටු හා තිරුවාණා ගල් උල් ආයුධ ලෙස භාවිත කළහ.")
        4 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ පූර්ව ඓතිහාසික යකඩ යුගයට අයත් මහා ශිලා සුසාන භූමියක් හමුවූ ස්ථානය කුමක්ද?", listOf("ඉබ්බන්කටුව (දඹුල්ල අසල)", "කතරගම", "කැළණිය", "ගාල්ල"), 0, "ඉබ්බන්කටුව සුසාන භූමියෙන් මැටි බඳුන්වල අළු තැන්පත් කළ ශිලා මංජුසා සුසාන සොයාගෙන ඇත.")
        5 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ ප්‍රාග් ඓතිහාසික යුගයේ මානවයා ජීවත් වූ ආකාරය පිළිබඳ නිවැරදි ප්‍රකාශය කුමක්ද?", listOf("ස්ථිර ගොවිතැන් කළහ", "දඩයම් කරමින් හා කැලෑ අල-කොළ ගෙඩි එක්රැස් කරමින් (වැදි ජන ජීවිතය)", "නගර නිර්මාණය කළහ", "කර්මාන්තශාලා පිහිටුවූහ"), 1, "ප්‍රාග් ඓතිහාසික මානවයා ලෙන්වල ජීවත් වෙමින් දඩයමින් සහ ස්වභාවික ආහාර එක්රැස් කරමින් දිවි ගෙවීය.")
        6 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ මුල්ම ආර්ය ජනාවාස ඇතිවූයේ කුමන ගංගා නිම්න ආශ්‍රිතවද?", listOf("මල්වතු ඔය, දැදුරු ඔය, වලවේ ගඟ", "කැළණි ගඟ පමණි", "මහවැලි ගඟ පමණි", "මහනුවර කඳුකරයේ"), 0, "විජය කුමරු ඇතුළු පිරිස පැමිණි පසු ජලය හා කෘෂිකර්මාන්තයට හිතකර ගංගා නිම්නවල ගම්මාන පිහිටුවා ගත්හ.")
        7 -> QuizQuestion(qNumber, "ශ්‍රී ලංකාවේ ප්‍රථම සංවිධානාත්මක අගනගරය ලෙස අනුරාධපුරය සැලසුම් කළ රජතුමා කවුද?", listOf("විජය රජු", "පණ්ඩුකාභය රජතුමා", "මුටසීව රජු", "දේවානම්පියතිස්ස රජු"), 1, "පණ්ඩුකාභය රජතුමා නගර ආරක්ෂක පවුරු, සුසාන භූමි, රෝහල් හා නගර පිරිසිදු කිරීමේ ක්‍රම සහිතව අනුරාධපුරය ගොඩනැගීය.")
        8 -> QuizQuestion(qNumber, "පණ්ඩුකාභය රජතුමා විසින් ඉදිකරන ලද අනුරාධපුරයේ පැරණිතම වැවක් වන්නේ කුමක්ද?", listOf("පරාක්‍රම සමුද්‍රය", "බසවක්කුලම (අභය වැව)", "කලා වැව", "මින්නේරිය වැව"), 1, "බසවක්කුලම හෙවත් අභය වැව නගරයේ ජල අවශ්‍යතාවය උදෙසා ක්‍රි.පූ. 4 වන සියවසේදී ඉදිවිය.")
        9 -> QuizQuestion(qNumber, "ලංකාවේ ඉතිහාසය විස්තර කෙරෙන පැරණිතම පාලි වංශකතාව කුමක්ද?", listOf("මහාවංශය", "දීපවංශය", "චූලවංශය", "රාජාවලිය"), 1, "දීපවංශය ක්‍රි.ව. 4 වන සියවසේදී ලියැවුණු පැරණිතම වංශකතාව වන අතර පසුව මහානාම හිමියන් මහාවංශය රචනා කළහ.")
        else -> QuizQuestion(qNumber, "පැරණි ශ්‍රී ලංකාවේ ලෙන් විහාරවල කටාරම් කොටා සටහන් කර ඇති අක්ෂර කලාව කුමක්ද?", listOf("දේවනාගරී", "මුල් බ්‍රාහ්මී අක්ෂර (Early Brahmi)", "රෝම අක්ෂර", "දෙමළ අක්ෂර"), 1, "'අගත අනගත චතුදිස සගස දිනේ' වැනි බ්‍රාහ්මී සෙල්ලිපි මඟින් සංඝයාට ලෙන් පූජා කිරීම වාර්තා කර ඇත.")
      }

      // SET 2: අනුරාධපුර යුගයේ ආරම්භය හා වාරි ශිෂ්ටාචාරය
      2 -> when (qIdx) {
